//! Filesystem writes that refuse to follow symlinks.
//!
//! Content produced by `maestro adapt` is derived from the scanned repo, so a
//! repo-planted symlink at an artifact path (`.maestro/knowledge.md`,
//! `docs/PRD.md`, `.claude/**`) would otherwise steer generated bytes into a
//! file outside the project (CWE-59 / CWE-73, security audit FS-2/FS-3).

use std::io;
use std::io::Write as _;
use std::path::Path;

/// True when `path` exists in any form, including a symlink — unlike
/// `Path::exists`, which follows links and reports a dangling symlink as
/// absent (the #1033 PRD pre-check bypass).
pub fn exists_no_follow(path: &Path) -> bool {
    std::fs::symlink_metadata(path).is_ok()
}

/// Atomically write `body` to `path` without following a symlink planted at
/// `path`.
///
/// - Refuses when `path` is a symlink (including a dangling one) or any other
///   non-regular existing target (directory, FIFO, ...). The check reads
///   `symlink_metadata`, which does not follow the final path component.
/// - Writes through a `create_new` temp file in the parent directory and
///   `rename`s it into place: readers never observe a partial write, and the
///   final `rename` cannot be redirected by a symlink swapped in mid-flight
///   (rename does not follow its destination).
/// - Parent-directory symlinks are the caller's concern; the scaffolder
///   additionally validates containment on canonicalized paths.
pub fn write_no_follow(path: &Path, body: &str) -> io::Result<()> {
    if let Ok(meta) = std::fs::symlink_metadata(path) {
        if meta.file_type().is_symlink() {
            return Err(io::Error::new(
                io::ErrorKind::PermissionDenied,
                format!("refusing to write {}: path is a symlink", path.display()),
            ));
        }
        if !meta.is_file() {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("refusing to write {}: not a regular file", path.display()),
            ));
        }
    }

    let parent = path.parent().ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("refusing to write {}: no parent directory", path.display()),
        )
    })?;
    let name = path.file_name().ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("refusing to write {}: no file name", path.display()),
        )
    })?;
    // The pid suffix keeps concurrent runs from fighting over one temp path;
    // a stale temp from a crashed run fails `create_new` loudly instead of
    // being silently reused.
    let temp = parent.join(format!(
        ".{}.{}.tmp",
        name.to_string_lossy(),
        std::process::id()
    ));

    let mut file = std::fs::OpenOptions::new()
        .create_new(true)
        .write(true)
        .open(&temp)?;
    let write_result = file.write_all(body.as_bytes());
    drop(file);
    match write_result.and_then(|()| std::fs::rename(&temp, path)) {
        Ok(()) => Ok(()),
        Err(e) => {
            let _ = std::fs::remove_file(&temp);
            Err(e)
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::TempDir;

    #[test]
    fn write_no_follow_creates_new_file() {
        let dir = TempDir::new().unwrap();
        let path = dir.path().join("out.md");

        write_no_follow(&path, "# Hello").unwrap();

        assert_eq!(std::fs::read_to_string(&path).unwrap(), "# Hello");
    }

    #[test]
    fn write_no_follow_replaces_regular_file() {
        let dir = TempDir::new().unwrap();
        let path = dir.path().join("out.md");
        std::fs::write(&path, "old").unwrap();

        write_no_follow(&path, "new").unwrap();

        assert_eq!(std::fs::read_to_string(&path).unwrap(), "new");
    }

    #[test]
    fn write_no_follow_refuses_symlinked_target_leaving_victim_untouched() {
        let dir = TempDir::new().unwrap();
        let victim = dir.path().join("victim.md");
        std::fs::write(&victim, "ORIGINAL").unwrap();
        let link = dir.path().join(".maestro");
        std::fs::create_dir_all(&link).unwrap();
        use std::os::unix::fs::symlink;
        symlink(&victim, link.join("knowledge.md")).unwrap();

        let err = write_no_follow(&link.join("knowledge.md"), "generated").unwrap_err();

        assert_eq!(std::fs::read_to_string(&victim).unwrap(), "ORIGINAL");
        assert!(
            err.to_string().contains("symlink"),
            "error should name the symlink refusal, got: {err}"
        );
    }

    #[test]
    fn write_no_follow_refuses_dangling_symlink() {
        let dir = TempDir::new().unwrap();
        let victim = dir.path().join("victim.md");
        let link = dir.path().join("PRD.md");
        use std::os::unix::fs::symlink;
        symlink(&victim, &link).unwrap();

        write_no_follow(&link, "generated PRD").unwrap_err();

        assert!(
            !victim.exists(),
            "dangling symlink must not be followed to create the target"
        );
        assert!(
            std::fs::symlink_metadata(&link)
                .unwrap()
                .file_type()
                .is_symlink()
        );
    }

    #[test]
    fn write_no_follow_refuses_directory_target() {
        let dir = TempDir::new().unwrap();
        let target = dir.path().join("subdir");
        std::fs::create_dir_all(&target).unwrap();

        write_no_follow(&target, "x").unwrap_err();

        assert!(target.is_dir());
    }

    #[test]
    fn exists_no_follow_sees_dangling_symlink_where_exists_does_not() {
        let dir = TempDir::new().unwrap();
        let link = dir.path().join("PRD.md");
        use std::os::unix::fs::symlink;
        symlink(dir.path().join("nowhere.md"), &link).unwrap();

        assert!(
            !link.exists(),
            "sanity: Path::exists follows the dangling link"
        );
        assert!(exists_no_follow(&link));
    }
}
